      if (/^\s*import\b/.test(text.slice(lineStart, m.index))) continue;
      

      const from = text.lastIndexOf("\n", Math.max(0, m.index - WINDOW)) + 1;
      const toNl = text.indexOf("\n", m.index + WINDOW);
      const around = text.slice(from, toNl === -1 ? text.length : toNl);
